namespace Boilerplate.Application.Common.Storage;

/// <summary>
/// Stores file content by key (ADR-0030). Keys are generated by the application, never taken from user input.
/// Metadata and tenant isolation live in the database; implementations only move bytes.
/// </summary>
public interface IFileStorage
{
    /// <summary>Stores <paramref name="content"/> under a new key.</summary>
    /// <exception cref="Exceptions.ConflictException">No storage is configured.</exception>
    Task WriteAsync(string key, Stream content, CancellationToken cancellationToken);

    /// <summary>Opens the content for reading, or returns <see langword="null"/> when nothing is stored under the key.</summary>
    /// <exception cref="Exceptions.ConflictException">No storage is configured.</exception>
    Task<Stream?> OpenReadAsync(string key, CancellationToken cancellationToken);

    /// <summary>Deletes the content. Deleting a key that holds nothing succeeds, so retries are safe.</summary>
    Task DeleteAsync(string key, CancellationToken cancellationToken);
}
